const $=id=>document.getElementById(id);
const fields=['seller','email','client','number','date','due','discount','tax','note'];
let kind='invoice',editing=null,docs=[];
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=new Date(),deadline=new Date(today);deadline.setDate(deadline.getDate()+30);$('date').value=iso(today);$('due').value=iso(deadline);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Math.max(0,Number(v)||0);
const money=v=>Number(v).toLocaleString('en-TN',{minimumFractionDigits:3,maximumFractionDigits:3})+' TND';
function addItem(desc='',qty=1,price=0){const row=document.createElement('div');row.className='item';row.innerHTML=`<label>Service<input class="desc" required value="${esc(desc)}" placeholder="e.g. Logo design"></label><label>Qty<input class="qty" type="number" min="0.001" step="0.001" required value="${qty}"></label><label>Price (TND)<input class="price" type="number" min="0" step="0.001" required value="${price}"></label><button type="button" aria-label="Remove service">×</button>`;row.querySelector('button').onclick=()=>{row.remove();render()};$('items').append(row);render()}
function data(){return {...Object.fromEntries(fields.map(f=>[f,$(f).value])),kind,lang:$('lang').value,items:[...document.querySelectorAll('.item')].map(r=>({desc:r.querySelector('.desc').value,qty:num(r.querySelector('.qty').value),price:num(r.querySelector('.price').value)}))}}
function amounts(d){const round=v=>Math.round((v+Number.EPSILON)*1000)/1000;const subtotal=round(d.items.reduce((s,i)=>s+round(i.qty*i.price),0)),discount=round(subtotal*Math.min(100,num(d.discount))/100),net=round(subtotal-discount),tax=round(net*Math.min(100,num(d.tax))/100);return{subtotal,discount,tax,total:round(net+tax)}}
const documentLabels={en:['INVOICE','QUOTE','BILL TO','Issue date','Due date','Service','Qty','Price','Amount','Subtotal','Discount','Tax','Total'],fr:['FACTURE','DEVIS','FACTURÉ À','Date','Échéance','Service','Qté','Prix','Montant','Sous-total','Remise','Taxe','Total'],ar:['فاتورة','عرض سعر','إلى','تاريخ','آخر أجل','الخدمة','الكمية','السعر','المجموع','المجموع الفرعي','التخفيض','الضريبة','الإجمالي']};
function render(){const d=data(),a=amounts(d),ar=d.lang==='ar',t=documentLabels[d.lang]||documentLabels.en;$('paper').dir=ar?'rtl':'ltr';$('paper').lang=d.lang;$('paper').innerHTML=`<div class="paper-top"><div><strong>${esc(d.seller)}</strong><div class="muted">${esc(d.email)}</div></div><div><h2>${t[d.kind==='invoice'?0:1]}</h2><div class="muted">${esc(d.number)}</div></div></div><div class="paper-meta"><div><div class="muted">${t[2]}</div><strong>${esc(d.client)}</strong></div><div class="muted">${t[3]}: ${esc(d.date)}<br>${t[4]}: ${esc(d.due)}</div></div><table><thead><tr>${t.slice(5,9).map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${d.items.map(i=>`<tr><td>${esc(i.desc)}</td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(Math.round(i.qty*i.price*1000)/1000)}</td></tr>`).join('')}</tbody></table><div class="totals"><div class="total-line"><span>${t[9]}</span><span>${money(a.subtotal)}</span></div>${a.discount?`<div class="total-line"><span>${t[10]} (${esc(d.discount)}%)</span><span>− ${money(a.discount)}</span></div>`:''}<div class="total-line"><span>${t[11]} (${esc(d.tax)}%)</span><span>${money(a.tax)}</span></div><div class="total-line grand"><span>${t[12]}</span><span>${money(a.total)}</span></div></div><div class="paper-note">${esc(d.note)}</div><div class="paper-bottom">${esc(d.seller)} · ${esc(d.number)}</div>`}
try{const stored=JSON.parse(localStorage.getItem('factoura-docs')||'[]');if(Array.isArray(stored))docs=stored.filter(d=>d&&Array.isArray(d.items))}catch{$('status').textContent='Saved documents could not be read.'}
function persist(){try{localStorage.setItem('factoura-docs',JSON.stringify(docs));return true}catch{$('status').textContent='Could not save: browser storage is unavailable.';return false}}
function nextReference(k){const prefix=(k==='invoice'?'INV':'QUO')+'-'+new Date().getFullYear()+'-';let n=1;while(docs.some(d=>d.number===prefix+String(n).padStart(3,'0')))n++;return prefix+String(n).padStart(3,'0')}
function switchKind(k){kind=k;$('invoice').classList.toggle('active',k==='invoice');$('quote').classList.toggle('active',k==='quote');if(!editing)$('number').value=nextReference(k);render()}
function validateDocument(){const d=data();if(!d.items.length){$('status').textContent='Add at least one service.';return false}if(d.due<d.date){$('status').textContent='The due date must be on or after the issue date.';return false}if(docs.some(x=>x.id!==editing&&x.number.trim()===d.number.trim())){$('status').textContent='This reference already exists. Choose another one.';return false}return true}
function updateSummary(){const invoices=docs.filter(d=>d.kind==='invoice');$('sum-total').textContent=money(invoices.reduce((s,d)=>s+amounts(d).total,0));$('sum-paid').textContent=money(invoices.filter(d=>d.paid).reduce((s,d)=>s+amounts(d).total,0));$('sum-pending').textContent=money(invoices.filter(d=>!d.paid).reduce((s,d)=>s+amounts(d).total,0))}
function history(){updateSummary()}
$('invoice').onclick=()=>switchKind('invoice');$('quote').onclick=()=>switchKind('quote');$('add').onclick=()=>addItem();$('form').addEventListener('input',render);$('lang').onchange=render;
$('form').onsubmit=e=>{e.preventDefault();if(!validateDocument())return;const old=docs.find(d=>d.id===editing),d={...data(),id:editing||crypto.randomUUID(),paid:old?.paid||false};const next=docs.filter(x=>x.id!==d.id);next.unshift(d);const prior=docs;docs=next;if(!persist()){docs=prior;return}editing=d.id;history();$('status').textContent='Document saved in this browser.'};
$('print').onclick=()=>{if($('form').reportValidity()&&validateDocument())window.print()};
$('saved').onclick=e=>{const b=e.target.closest('button');if(!b)return;const d=docs.find(x=>x.id===b.dataset.id);if(!d)return;if(b.dataset.action==='open'){editing=d.id;fields.forEach(f=>$(f).value=d[f]);$('lang').value=d.lang||'en';$('items').innerHTML='';d.items.forEach(i=>addItem(i.desc,i.qty,i.price));switchKind(d.kind);$('form').scrollIntoView({behavior:'smooth'});$('status').textContent='Editing '+d.number}else if(b.dataset.action==='paid'){const prior=d.paid;d.paid=!d.paid;if(!persist())d.paid=prior;history()}else if(confirm('Delete this saved document?')){const prior=docs;docs=docs.filter(x=>x.id!==d.id);if(!persist())docs=prior;else if(editing===d.id)editing=null;history()}};
$('new').onclick=()=>{if(editing===null&&data().client&&!confirm('Start a new document? Unsaved changes will be lost.'))return;editing=null;$('client').value='';$('date').value=iso(new Date());const d=new Date();d.setDate(d.getDate()+30);$('due').value=iso(d);$('discount').value='0';$('tax').value='0';$('number').value=nextReference(kind);$('items').innerHTML='';addItem();$('status').textContent='New document. Your business details have been kept.';$('client').focus();render()};
$('backup').onclick=()=>{const blob=new Blob([JSON.stringify({format:'factoura',version:1,documents:docs},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='b0rk3n-backup-'+iso(new Date())+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Backup downloaded.'};
addItem('Brand identity — starter package',1,850);addItem('Social media assets',3,75);$('number').value=nextReference(kind);render();
